extern const uint8_t  gp_cal_offseq[GP_CAL_OFFSEQ_N]; /* 0x63555 */
extern const uint16_t gp_cal_ratio[10];               /* 0x4FAA4 gear -1..8, x1000 */
extern const uint16_t gp_cal_sync_thr;                /* 0x1FF1F6 rpm */

